// NyaLink smoke test against mock-core (Node 22 native WebSocket)
const ws = new WebSocket('ws://localhost:7788/nyalink');
let id = 0;
const pending = new Map();
function req(topic, data) {
  return new Promise((res, rej) => {
    const rid = 'smoke-' + (++id);
    pending.set(rid, { res, rej });
    ws.send(JSON.stringify({ v: 1, id: rid, type: 'req', topic, data }));
    setTimeout(() => rej(new Error('timeout ' + topic)), 3000);
  });
}
let eyeStates = 0, lastState = null;
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) {
    const p = pending.get(m.id); pending.delete(m.id);
    m.type === 'err' ? p.rej(new Error(m.data.code + ':' + m.data.message)) : p.res(m.data);
  } else if (m.type === 'event' && m.topic === 'eye.state') { eyeStates++; lastState = m.data; }
};
ws.onopen = async () => {
  try {
    // 1. ping before hello must fail EAUTH
    let eauth = false;
    try { await req('sys.ping', {}); } catch (e) { eauth = /EAUTH/.test(e.message); }
    console.log('1 pre-hello EAUTH:', eauth ? 'PASS' : 'FAIL');
    // 2. hello no token
    const h = await req('sys.hello', { client: 'web', version: '0.0.1', token: null });
    console.log('2 hello pairingRequired:', h.pairingRequired ? 'PASS' : 'FAIL ' + JSON.stringify(h));
    // 3. pair
    const p = await req('sys.pair', { code: '000000', name: 'smoke' });
    console.log('3 pair token+role:', p.token && p.role ? 'PASS role=' + p.role : 'FAIL');
    // 4. ping
    const pg = await req('sys.ping', {});
    console.log('4 ping t:', typeof pg.t === 'number' ? 'PASS' : 'FAIL');
    // 5. wait eye.state heartbeat
    await new Promise(r => setTimeout(r, 2500));
    console.log('5 eye.state events:', eyeStates > 0 ? `PASS (${eyeStates}, mode=${lastState?.expression?.mode}, seq=${lastState?.seq})` : 'FAIL');
    // 6. eye.look then observe gaze target
    await req('eye.look', { x: 0.5, y: -0.3, hold: 2 });
    await new Promise(r => setTimeout(r, 300));
    const g = lastState?.gaze;
    console.log('6 eye.look applied:', g?.mode === 'target' && Math.abs(g.x - 0.5) < 1e-6 ? 'PASS' : 'FAIL ' + JSON.stringify(g));
    // 7. eye.mode
    await req('eye.mode', { mode: 'happy' });
    await new Promise(r => setTimeout(r, 300));
    console.log('7 eye.mode happy:', lastState?.expression?.mode === 'happy' ? 'PASS' : 'FAIL ' + lastState?.expression?.mode);
    // 8. unknown topic
    let enf = false;
    try { await req('nope.nope', {}); } catch (e) { enf = /ENOTFOUND/.test(e.message); }
    console.log('8 unknown ENOTFOUND:', enf ? 'PASS' : 'FAIL');
    // 9. reconnect with token
    const ws2 = new WebSocket('ws://localhost:7788/nyalink');
    ws2.onopen = () => ws2.send(JSON.stringify({ v: 1, id: 'r1', type: 'req', topic: 'sys.hello', data: { client: 'web', version: '0.0.1', token: p.token } }));
    ws2.onmessage = (ev) => {
      const m = JSON.parse(ev.data);
      if (m.id === 'r1') {
        console.log('9 token reuse hello:', m.data.device && m.data.role ? 'PASS role=' + m.data.role : 'FAIL ' + JSON.stringify(m.data));
        process.exit(0);
      }
    };
  } catch (e) { console.error('SMOKE FAIL:', e); process.exit(1); }
};
ws.onerror = (e) => { console.error('ws error', e.message); process.exit(1); };
setTimeout(() => { console.error('overall timeout'); process.exit(1); }, 15000);

