let st = await api(`/devices/${DEV}/stats`, {}, token);
const day = st.data?.daily?.[st.data.daily.length - 1];
P('9 stats', st.status < 300 && st.data?.current?.online === true && (day?.framesDown ?? 0) > 0, JSON.stringify({ current: st.data?.current, day }));
