const ws = new WebSocket('ws://localhost:7788/nyalink');
let id = 0; const pend = new Map(); let patches = [];
const req = (topic, data) => new Promise((res, rej) => {
  const rid = 'n-' + (++id); pend.set(rid, { res, rej });
  ws.send(JSON.stringify({ v: 1, id: rid, type: 'req', topic, data }));
