    // find current food value
    const food = JSON.stringify(tree).match(/"value":"(\d+)"/);
    await req('ui.event', { pluginId: 'feeder', componentId: 'feed', event: 'tap', command: 'feed.now', args: { grams: 20 }, values: { amount: 20, sched: true, times: ['07:00','19:00'] } });
